// Send sends a request to Codex and returns the final text output.
func (c *Client) Send(ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions) (string, error) {
	if opts.ImageFile != "" {
		return "", errors.New(i18n.T("codex_image_file_not_supported"))
	}
	if c.ApiClient == nil {
		if err := c.configure(); err != nil {
			return "", err
		}
	}

	req := c.buildCodexResponseParams(msgs, opts)
	stream := c.ApiClient.Responses.NewStreaming(ctx, req)
	defer stream.Close()

	var (
		builder       strings.Builder
		doneText      string
		completedResp *responses.Response
	)
	for stream.Next() {
		event := stream.Current()
		switch event.Type {
		case string(constant.ResponseOutputTextDelta("").Default()):
			builder.WriteString(event.AsResponseOutputTextDelta().Delta)
		case string(constant.ResponseOutputTextDone("").Default()):
			doneText = event.AsResponseOutputTextDone().Text
		case "response.completed":
			resp := event.AsResponseCompleted().Response
			completedResp = &resp
		}
	}

	if err := c.mapRequestError(stream.Err()); err != nil {
		return "", err
	}
	if completedResp != nil {
		// The Codex backend may send a sparse response.completed envelope even
		// after streaming the output text. Do not let that empty envelope erase
		// text collected from the preceding stream events.
		if text := c.ExtractText(completedResp); text != "" {
			return text, nil
		}
	}
	if builder.Len() > 0 {
		return builder.String(), nil
	}

	// Most Responses API streams include deltas, but a done-only stream still
	// carries the complete output and is valid input for this client.
	return doneText, nil
}

